        $failures[] = ['mutated immutable', $method, $valueUnit, $value, $overflowUnit, $base->format('c'), $original->format('c'), $immutable->format('c')];
    }
    if (!$mResult->format('Y-m-d H:i:s.u') === $iResult->format('Y-m-d H:i:s.u')) {
        // placeholder
    }
    if ($mResult->format('Y-m-d H:i:s.u') !== $iResult->format('Y-m-d H:i:s.u')) {
        $failures[] = ['mismatch', $method, $valueUnit, $value, $overflowUnit, $base->format('Y-m-d H:i:s.u'), $mResult->format('Y-m-d H:i:s.u'), $iResult->format('Y-m-d H:i:s.u')];
    }
    if ($iResult->lessThan($start) || $iResult->greaterThan($end)) {
        $failures[] = ['out of range', $method, $valueUnit, $value, $overflowUnit, $base->format('Y-m-d H:i:s.u'), $start->format('Y-m-d H:i:s.u'), $end->format('Y-m-d H:i:s.u'), $iResult->format('Y-m-d H:i:s.u')];
    }
    if (count($failures) > 20) {
        break;
    }
}
echo $failures === [] ? "ALL OK\n" : print_r($failures, true);
